SELECT c.id, c.user_id, c.subject_id, c.type, c.rate, c.ep_status,
       c.created_at, c.updated_at,
       s.name, s.name_cn, s.image, s.score, s.eps, s.air_date, s.air_weekday,
       s.type AS subject_type
FROM user_collection c
JOIN subject s ON s.id = c.subject_id
WHERE c.user_id = #{userId}
  AND s.air_date BETWEEN #{startDate} AND #{endDate}
 AND s.air_weekday = #{weekday} 
ORDER BY s.air_weekday, s.score DESC

SELECT subject_id
FROM user_collection
WHERE user_id = #{userId}
  AND subject_id IN

    #{subjectId}
